   */
  lemma multshrDivisionProperty(x: int, y: int, k: int)
    requires k >= 0
    ensures (x * y) >= 0 ==> (x * y) / Pow2(k) == (x * y) / Pow2(k)
    ensures (x * y) < 0 ==> (x * y) / Pow2(k) == -((-(x * y)) / Pow2(k))
  {
    // This lemma follows from the definition of integer division
